import sys
from functools import lru_cache
from typing import List

def maximize_score(S: str, arr: List[int]) -> int:
    n, N = len(S), len(arr)
    NEG = float("-inf")
    # g[c]: best score to clear c adjacent equal chars (pieces of size 1..N)
    g = [0] + [NEG] * n
    for c in range(1, n + 1):
        for t in range(1, min(c, N) + 1):
            if g[c - t] != NEG:
                g[c] = max(g[c], g[c - t] + arr[t - 1])
    sys.setrecursionlimit(10000)

    @lru_cache(maxsize=None)
    def f(l: int, r: int, k: int):
        if l > r:
            return 0
        best = g[k + 1] + f(l + 1, r, 0)
        for m in range(l + 1, r + 1):
            if S[m] == S[l]:
                best = max(best, f(l + 1, m - 1, 0) + f(m, r, k + 1))
        return best

    return f(0, n - 1, 0)
